package com.yeyamo_mobile.api.partner_service.infrastructure.messaging;
import java.util.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.partner_service.application.PartnerService;import com.yeyamo_mobile.api.partner_service.domain.model.PartnerStatus;
@Component public class PartnerDecisionConsumer{private final ObjectMapper mapper;private final PartnerService service;private final PartnerProcessedEventRepository processed;public PartnerDecisionConsumer(ObjectMapper m,PartnerService s,PartnerProcessedEventRepository p){mapper=m;service=s;processed=p;}@KafkaListener(topics="${yeyamo.kafka.topics.admin-events:admin.events}",groupId="${spring.kafka.consumer.group-id:partner-service}")@Transactional public void consume(String raw)throws Exception{JsonNode e=mapper.readTree(raw);String type=text(e,"eventType");Map<String,PartnerStatus>types=Map.of("partner.under_review",PartnerStatus.UNDER_REVIEW,"partner.approved",PartnerStatus.APPROVED,"partner.rejected",PartnerStatus.REJECTED,"partner.needs_info",PartnerStatus.NEEDS_INFO,"partner.requires_changes",PartnerStatus.REQUIRES_CHANGES);if(!types.containsKey(type))return;UUID eventId=UUID.fromString(text(e,"eventId"));if(processed.existsById(eventId))return;JsonNode p=e.path("payload");UUID partnerId=UUID.fromString(text(p,"partnerId"));Integer risk=p.hasNonNull("riskScore")?p.get("riskScore").asInt():null;service.applyDecision(partnerId,types.get(type),text(p,"reviewComment"),risk,text(e,"correlationId"));processed.save(new PartnerProcessedEvent(eventId,type));}private String text(JsonNode n,String f){JsonNode v=n.get(f);return v==null||v.isNull()?null:v.asText();}}
